-- Phase 2: the quiz.
--
-- Safe to re-run. Adds the two columns the Quiz tab reads, then replaces the
-- question bank with the rebalanced 20-question set.
--
-- `topic` is the subject each row leads with, because every question opens
-- with the same six words. `choices` holds four options, exactly one correct;
-- the DVSA publishes no wrong answers, so those are written for this app.

begin;

alter table show_me_tell_me add column if not exists topic text;
alter table show_me_tell_me add column if not exists choices jsonb default '[]';

-- Replaced wholesale rather than updated in place: the old single
-- "under the bonnet" row became three, so there is no row-to-row mapping.
delete from show_me_tell_me;


commit;
